#!/usr/bin/env bash
# 3Rivers mobile API — apply dashboard count fix + seed demo data.
# Run on onshore01 as root:  bash /root/finish-3rivers-mobile.sh
set -euo pipefail
APP=/opt/3rivers/app
TS=$(date +%Y%m%d-%H%M%S)

echo "== 1/3  refresh mobile_v1.py (dashboard supplier/vendor count fix) =="
cp "$APP/mobile_v1.py" "$APP/mobile_v1.py.bak-$TS" 2>/dev/null || true
base64 -d > "$APP/mobile_v1.py" <<'MV1_B64'

MV1_B64
chown three_rivers:three_rivers "$APP/mobile_v1.py"
"$APP/venv/bin/python" -c "import ast; ast.parse(open('$APP/mobile_v1.py').read()); print('  syntax OK')"

echo "== 2/3  seed demo work orders + shipments =="
base64 -d > /tmp/seed_3rivers.py <<'SEED_B64'

SEED_B64
set -a; . /etc/3rivers/bisera.env; set +a
sudo -u three_rivers --preserve-env=BISERADB_BASE_URL,BISERADB_NAMESPACE,BISERADB_API_KEY \
  "$APP/venv/bin/python" /tmp/seed_3rivers.py
rm -f /tmp/seed_3rivers.py

echo "== 3/3  restart API + verify =="
systemctl restart 3rivers-api
sleep 2
echo "  active: $(systemctl is-active 3rivers-api)"
curl -s -o /dev/null -w "  no-auth /api/v1/dashboard -> %{http_code} (want 401)\n" https://3rivers.onshoretech.ai/api/v1/dashboard
echo "Done."
